114|const FALLBACK_ROLES = ['ADMIN', 'USER', 'DEVELOPER'] as const;
115|
116|export const usersQueryKeys = {
117|  all: ['users'] as const,
118|  meta: () => [...usersQueryKeys.all, 'meta'] as const,
119|  list: (params: UsersListQuery) => [...usersQueryKeys.all, 'list', params] as const,
