122|const normalizeUserItems = (items: unknown[]): UserRecord[] => {
123|  return items.map((item) => {
124|    const record = item as UserRecord & { role?: string };
125|    const roles = Array.isArray(record.roles)
126|      ? record.roles.map((role) => String(role).toUpperCase())
127|      : [String(record.role || 'USER').toUpperCase()];
128|    const uniqueRoles = Array.from(new Set(roles));
129|
130|    return {
131|      ...record,
132|      roles: uniqueRoles,
133|      role: uniqueRoles[0] || 'USER',
134|    };
135|  });
136|};
137|
138|const normalizeAvailableRoles = (items: RoleRecord[]): string[] => {
139|  const fromApi = items
140|    .map((role) => String(role.name || '').toUpperCase())
141|    .filter(Boolean);
142|  return Array.from(new Set([...FALLBACK_ROLES, ...fromApi]));
143|};
