145|export const normalizeBaseInfoOptions = (items: unknown[], excludeRootId: string): BaseInfoOption[] => {
146|  return (items as Array<{ id: string | number; label?: string; title?: string; ui_html?: string | null }>)
147|    .filter((item) => String(item.id) !== excludeRootId)
148|    .map((item) => ({
149|      id: String(item.id),
150|      label: String(item.label || item.title || item.id),
151|      uiHtml: item.ui_html ?? null,
152|    }));
153|};
