155|const getUsersLoadErrorMessage = (data: unknown, fallback: string): string => {
156|  if (!data || typeof data !== 'object') {
157|    return fallback;
158|  }
159|
160|  const payload = data as { error?: string };
161|  return typeof payload.error === 'string' && payload.error.trim() ? payload.error : fallback;
162|};
