164|export async function fetchUsersList(
165|  query: UsersListQuery = {},
166|  signal?: AbortSignal,
167|): Promise<{ items: UserRecord[]; totalCount: number }> {
168|  const searchParams = new URLSearchParams();
169|  appendUsersListParams(searchParams, query);
170|  const queryString = searchParams.toString();
171|  const url = queryString ? `/api/users?${queryString}` : '/api/users';
172|
173|  const { data: usersData, response: usersResponse } = await apiGet<ApiListResponse>(url, { signal });
174|
175|  if (!usersResponse.ok) {
176|    throw new Error(getUsersLoadErrorMessage(usersData, `Failed to load users (HTTP ${usersResponse.status}).`));
177|  }
178|
179|  if (!usersData.success) {
180|    throw new Error(getUsersLoadErrorMessage(usersData, 'Failed to load users.'));
181|  }
182|
183|  const items = normalizeUserItems(usersData.items ?? []);
184|  const totalCount = typeof usersData.totalCount === 'number'
185|    ? usersData.totalCount
186|    : items.length;
187|
188|  return { items, totalCount };
189|}
