191|export async function fetchUsersPageMeta(): Promise<UsersPageMeta> {
192|  const [rolesResult, genderResult, personTypeResult] = await Promise.allSettled([
193|    apiGet<ApiListResponse<RoleRecord>>('/api/roles'),
194|    apiGet<ApiListResponse>('/api/base-info/options?root=100&lang=en'),
195|    apiGet<ApiListResponse>('/api/base-info/options?root=102&lang=en'),
196|  ]);
197|
198|  const rolesData = rolesResult.status === 'fulfilled' ? rolesResult.value.data : null;
199|  const genderData = genderResult.status === 'fulfilled' ? genderResult.value.data : null;
200|  const personTypeData = personTypeResult.status === 'fulfilled' ? personTypeResult.value.data : null;
201|
202|  const availableRoles = rolesData?.success
203|    ? normalizeAvailableRoles((rolesData.items ?? []) as RoleRecord[])
204|    : [...FALLBACK_ROLES];
205|
206|  const genderOptions = genderData?.success
207|    ? normalizeBaseInfoOptions(genderData.items ?? [], '100')
208|    : [];
209|
210|  const personTypeOptions = personTypeData?.success
211|    ? normalizeBaseInfoOptions(personTypeData.items ?? [], '102')
212|    : [];
213|
214|  return {
215|    availableRoles,
216|    genderOptions,
217|    personTypeOptions,
218|  };
